use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::{BTreeMap,BTreeSet},fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/three-lane-final-exp176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-07-three-lane-final-exp176";const CACHE:&str="/home/ubuntu/src/zopro-perf-work/three-lane-miller176/synthetic-fixtures.json";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn interval(mut x:Vec<f64>)->[f64;4]{assert_eq!(x.len(),31);let wins=x.iter().filter(|&&v|v<1.).count();x.sort_by(f64::total_cmp);[x[9],x[15],x[21],wins as f64]}
fn same(row:&Value,v:[f64;4]){for(k,x)in["low","median","high","wins"].into_iter().zip(v){assert!((row[k].as_f64().unwrap()-x).abs()<1e-10);}}
fn walk(root:&Path,base:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(base).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(root,&p,out)}else{out.push(p.strip_prefix(root).unwrap().to_path_buf());}}}
fn main(){
 let a=read(r("analysis.json"));let jobs=read(r("jobs.json"));let fixture=read(CACHE);let mut table=BTreeMap::new();let mut observations=BTreeMap::new();let mut calls=0usize;
 for j in jobs.as_array().unwrap(){let n=j["name"].as_str().unwrap();let v:Value=serde_json::from_str(fs::read_to_string(r(format!("capture/{n}/stdout.log"))).unwrap().trim()).unwrap();for k in["arm","endpoint","workers","rounds"]{assert_eq!(v[k],j[k]);}assert_eq!(v["endpoint"],"full");assert_eq!(v["primes"],7);let rounds=v["rounds"].as_u64().unwrap()as usize;let mut samples=v["samples_ns"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).collect::<Vec<_>>();assert_eq!(samples.len(),rounds);assert_eq!(v["checked_outputs"].as_u64().unwrap()as usize,rounds);samples.sort_unstable();assert_eq!(v["median_ns"].as_u64().unwrap(),samples[rounds/2]);
  let ids=[3usize,4,6,8,9,11,12,13];let mut sha=Sha256::new();for i in 0..rounds{for word in fixture["fixtures"][ids[i%8]]["final"].as_array().unwrap().iter().flat_map(|v|v.as_array().unwrap()){sha.update(word.as_u64().unwrap().to_le_bytes());}}assert_eq!(format!("{:x}",sha.finalize()),v["output_sha256"].as_str().unwrap());
  let w=v["workers"].as_u64().unwrap()as usize;let pins=v["worker_pins"].as_array().unwrap();assert_eq!(pins.len(),w);let(mut indices,mut tids)=(BTreeSet::new(),BTreeSet::new());for p in pins{let i=p["index"].as_u64().unwrap()as usize;assert!(i<w&&indices.insert(i));assert_eq!(p["cpu"].as_u64().unwrap()as usize,if w==1{2}else{i});assert!(p["tid"].as_u64().unwrap()>0&&tids.insert(p["tid"].as_u64().unwrap()));}
  if j["panel"]=="latency"{table.insert((w,j["arm"].as_str().unwrap().to_string(),j["block"].as_u64().unwrap()as usize),samples[rounds/2]as f64);}calls+=rounds+7;observations.insert(n.to_string(),v);
 }
 let at=|w:usize,arm:&str,b:usize|table[&(w,arm.to_string(),b)];let mut failure=BTreeSet::new();let mut aggregate=BTreeMap::from([("native",vec![1f64;31]),("fresh",vec![1f64;31]),("packed",vec![1f64;31])]);let mut count=0;
 for row in a["contexts"].as_array().unwrap(){let w=row["workers"].as_u64().unwrap()as usize;let c=interval((0..31).map(|b|at(w,"fresh",b)/at(w,"native",b)).collect());same(&row["fresh_native_calibration"],c);if c[0]<1./1.03||c[2]>1.03{failure.insert(format!("calibration w{w}"));}count+=1;
  for control in["native","fresh","packed"]{let ratios=(0..31).map(|b|at(w,"fully",b)/at(w,control,b)).collect::<Vec<_>>();for b in 0..31{aggregate.get_mut(control).unwrap()[b]*=ratios[b].powf(1./3.);}let c=interval(ratios);same(&row[format!("fully_{control}")],c);if c[2]>1.03{failure.insert(format!("nonregression w{w}/{control}"));}count+=1;if w==32{if c[2]>=1.||c[3]<21.{failure.insert(format!("gain w32/{control}"));}count+=1;}}
 }
 for control in["native","fresh","packed"]{let c=interval(aggregate.remove(control).unwrap());same(&a["all3"][control],c);if c[2]>=1.||c[3]<21.{failure.insert(format!("gain all3/{control}"));}count+=1;}assert_eq!(count,18);assert_eq!(failure,a["failed_checks"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect());assert_eq!(a["gate_passed"],failure.is_empty());
 let mut receipts=0;for s in read(r("capture-plan.json"))["steps"].as_array().unwrap(){let n=s["name"].as_str().unwrap();let base=r(format!("capture/{n}"));let e=read(base.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for(f,key)in[("stdout.log","stdout_sha256"),("stderr.log","stderr_sha256")]{assert_eq!(hash(base.join(f)),e[key].as_str().unwrap());}receipts+=1;}
 let mut pmu=vec![];let mut headers=vec![];for j in jobs.as_array().unwrap(){let n=j["name"].as_str().unwrap();if j["panel"]=="stat"{let data=fs::read_to_string(j["data"].as_str().unwrap()).unwrap();let mut values=BTreeMap::new();for line in data.lines().filter(|l|!l.trim().is_empty()&&!l.starts_with('#')){let p=line.split(';').collect::<Vec<_>>();assert_eq!(p[4].trim().parse::<f64>().unwrap(),100.);values.insert(p[2].to_string(),p[0].trim().parse::<u64>().unwrap());}assert_eq!(values.len(),4);pmu.push(json!({"job":n,"counts":values,"all_running_percent":100,"calls":8192}));}
  if j["panel"]=="profile"{let v=&observations[n];let threads=v["worker_pins"].as_array().unwrap().iter().map(|p|(p["tid"].as_u64().unwrap(),p["cpu"].as_u64().unwrap())).collect::<BTreeMap<_,_>>();let mut pids=BTreeSet::new();let mut samples=0;for line in fs::read_to_string(r(format!("capture/samples-{n}/stdout.log"))).unwrap().lines().filter(|l|l.contains("cycles:u:")){let f=line.split_whitespace().collect::<Vec<_>>();let ids=f[1].split('/').collect::<Vec<_>>();let pid=ids[0].parse::<u64>().unwrap();let tid=ids[1].parse::<u64>().unwrap();let cpu=f[2].trim_matches(['[',']']).parse::<u64>().unwrap();assert_eq!(f[4].parse::<u64>().unwrap(),4_000_000);if let Some(expected)=threads.get(&tid){assert_eq!(*expected,cpu);}else{assert_eq!(tid,pid);let w=j["workers"].as_u64().unwrap();assert!(if w==1{cpu==2}else{cpu<w});}pids.insert(pid);samples+=1;}assert_eq!(pids.len(),1);headers.push(json!({"job":n,"samples":samples,"unique_pid":true,"period_4M":true,"worker_or_coordinator_TID_CPU_binding":true,"exact_ELF_IP_parser":false}));}
 }
 let result=json!({"passed":true,"independent_raw_timing_reconstruction":true,"gate_checks":count,"failed_checks":failure,"complete_processes":jobs.as_array().unwrap().len(),"calls_including_primes":calls,"all_digests_reconstructed_from_reused_cache":true,"all_worker_pin_sets_valid":true,"successful_receipts_and_streams":receipts,"PMU":pmu,"sample_header_checks":headers,"no_capture_or_oracle_replay":true});assert!(!r("independent-review.json").exists());fs::write(r("independent-review.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();
 let dest=Path::new(D);let before=fs::read_to_string(dest.join("README.md")).unwrap();fs::write(r("README-before-editorial.md"),&before).unwrap();let lead="**The new complete-consumer gate fails. Production remains unchanged.**";assert!(before.contains(lead));let mut body=before.replace(lead,"**The lane-wise finish is slower than the prior packed-Miller/scalar-finish strategy at every worker count. At 32 workers its paired regression is 12.41%. All control calibrations pass; 13 of 18 checks fail.** Production remains unchanged.");
 body=body.replace("Ryzen9 9950X","Ryzen 9 9950X").replace("80complete","80 complete").replace("80conjugates","80 conjugates").replace("960Frobenius","960 Frobenius").replace("160easy","160 easy").replace("80cyclotomic","80 cyclotomic").replace("All15zero","All 15 zero").replace("512KiB","512 KiB").replace("101timed","101 timed").replace("after7checked","after 7 checked").replace("median101samples","median 101 samples").replace("1,920bytes","1,920 bytes");
 body.push_str("\n## Independent review and interpretation\n\nAn independent reader reconstructs all 18 checks from raw process medians, all 396 complete-output digests from the reused canonical cache, 427 command receipts/stream hashes, and every worker CPU/TID set. All six PMU groups report 100% running. Header checks bind each profile's PID, 4M period and sampled TID/CPU to its observed workers or coordinator; this is not an independent ELF/IP or LOST-record parser. [Review](artifacts/independent-review.json), [reader](artifacts/review.rs).\n\nThe solo result retains a positive comparison with native policy: ratio 0.850286 [0.849671, 0.851772], 31/31 wins. It still loses all 31 comparisons with prior packed solo, as do the 16/32-worker cases. At 32 workers, fully/native is 1.168962 [1.135681, 1.191051], 2/31 wins; fully/fresh is 1.163744 [1.137994, 1.178178], 0/31 wins; fully/prior packed is 1.124066 [1.116790, 1.132486], 0/31 wins. These calibrated regressions independently close this implementation.\n\nAbsolute native/fresh/prior timings differ from the earlier study. Do not infer a regression or improvement of unchanged production from cross-study numbers. Earlier calibrated raw-Miller gains remain evidence in their original consumer; they did not establish full-proof gains. LLVM may coalesce identical old/new packed square or nonresidue helpers, so an old-module symbol in the new profile is not evidence of a fallback. The actual fully arm runs the new final-exponentiation body. No cause of the timing differences is isolated by this study.\n");fs::write(dest.join("README.md"),body).unwrap();for name in["review.rs","independent-review.json"]{fs::copy(r(name),dest.join("artifacts").join(name)).unwrap();}
 let mut files=vec![PathBuf::from("README.md")];walk(dest,&dest.join("artifacts"),&mut files);files.sort();fs::write(dest.join("SHA256SUMS"),files.iter().map(|p|format!("{}  {}\n",hash(dest.join(p)),p.display())).collect::<String>()).unwrap();println!("IndependentreviewPASS:18checks/396digests/427receipts;13failures retained;allcalibrationsPASS");
}
